static void ticker_draw_char(char c, int16_t x, uint8_t y, uint8_t scale) {
    if (c < 32 || c > 126) c = ' ';
    for (uint8_t col = 0; col < 5; col++) {
        uint8_t bits = pgm_read_byte(&ticker_font5x7[((uint16_t)(c - 32)) * 5 + col]);
        for (uint8_t row = 0; row < 7; row++) {
            if (!((bits >> row) & 1)) continue;
            for (uint8_t sx = 0; sx < scale; sx++) {
                int16_t px = x + (int16_t)col * scale + sx;
                if (px < 0 || px >= 128) continue;
                for (uint8_t sy = 0; sy < scale; sy++) {
                    oled_write_pixel((uint8_t)px, y + row * scale + sy, true);
                }
            }
        }
    }
}


oled_rotation_t oled_init_user(oled_rotation_t rotation) {
    return OLED_ROTATION_0;
}

bool oled_task_user(void) {

    // Scrolling text ticker (pixel-rendered, scalable font)
    uint16_t msg_len = sizeof(ticker_msg) - 1; // exclude null terminator
    if (msg_len == 0) return false;

    // Step the scroll position on a timer, independent of frame rate
    if (timer_elapsed32(ticker_last_step) >= TICKER_STEP_MS) {
        ticker_pos = (ticker_pos + 1) % msg_len;
        ticker_last_step = timer_read32();
    }

    oled_clear();

    uint8_t ticker_y = (32 - (7 * TICKER_SCALE)) / 2;
    for (uint8_t i = 0; i < TICKER_VISIBLE_CHARS; i++) {
        char c = pgm_read_byte(&ticker_msg[(ticker_pos + i) % msg_len]);
        ticker_draw_char(c, (int16_t)i * 6 * TICKER_SCALE, ticker_y, TICKER_SCALE);
    }

    return false; // true = let board render default dashboard, false = we handled it ourselves
}


